mapper.delete:
DELETE FROM activity_item
WHERE id = #{id}
AND source_type = 'PERSONAL'
AND owner_user_id = #{userId}

mapper.select:
SELECT 
FROM activity_item
WHERE id = #{id}
AND source_type = 'PERSONAL'
AND owner_user_id = #{userId}

SELECT FROM activity_item
source_type = 'PERSONAL' AND owner_user_id = #{userId}
source_type = 'PUBLIC' AND owner_user_id IS NULL
AND (#{cityJson} = '[]' OR JSON_OVERLAPS(city, #{cityJson})) AND (#{locationJson} = '[]' OR JSON_OVERLAPS(location, #{locationJson})) AND (#{activityTimeJson} = '[]' OR JSON_OVERLAPS(activity_time, #{activityTimeJson})) AND (#{moodJson} = '[]' OR JSON_OVERLAPS(mood, #{moodJson})) AND (#{sceneJson} = '[]' OR JSON_OVERLAPS(scene, #{sceneJson})) AND (#{budgetJson} = '[]' OR JSON_OVERLAPS(budget, #{budgetJson})) AND (#{activityTypeJson} = '[]' OR JSON_OVERLAPS(activity_type, #{activityTypeJson})) AND (#{styleJson} = '[]' OR JSON_OVERLAPS(style, #{styleJson})) AND (#{durationJson} = '[]' OR JSON_OVERLAPS(duration, #{durationJson}))
ORDER BY updated_at DESC LIMIT #{limit}
